import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"隨","description":"焦氏易林注 - 隨","frontmatter":{"title":"隨","description":"焦氏易林注 - 隨"},"headers":[],"relativePath":"zh/classics/jiaoyilin/017.md","filePath":"zh/classics/jiaoyilin/017.md"}'),l={name:"zh/classics/jiaoyilin/017.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="隨" tabindex="-1">隨 <a class="header-anchor" href="#隨" aria-label="Permalink to “隨”">​</a></h1><h3 id="隨-1" tabindex="-1">隨 <a class="header-anchor" href="#隨-1" aria-label="Permalink to “隨”">​</a></h3><h3 id="隨之乾" tabindex="-1">隨之乾 <a class="header-anchor" href="#隨之乾" aria-label="Permalink to “隨之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>鼻目易處，不知香臭。君迷於事，失其寵位。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此取《隨》象。艮為鼻，大離為目，艮在離上，故曰易處。巽為臭，兌昧，故不知香臭。震為君，坤為迷、為事，一陽居二陰下，故曰君迷於事。陽在下故失位。</p><h3 id="隨之坤" tabindex="-1">隨之坤 <a class="header-anchor" href="#隨之坤" aria-label="Permalink to “隨之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>唐虞相輔，鳥獸喜舞。安樂無事，國家富有。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此仍取《隨》象。震為帝、為唐虞，正反震，故曰相輔。艮為鳥、為獸，震為喜、為舞、為樂，坤為國家。○安樂，依宋元本，汲古作康。</p><h3 id="隨之屯" tabindex="-1">隨之屯 <a class="header-anchor" href="#隨之屯" aria-label="Permalink to “隨之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>左輔右弼，金玉滿堂。常盈不亡，富如厫倉。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《坤》。</p><h3 id="隨之蒙" tabindex="-1">隨之蒙 <a class="header-anchor" href="#隨之蒙" aria-label="Permalink to “隨之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>蒼龍單獨，與石相觸，摧折兩角。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《屯》。</p><h3 id="隨之需" tabindex="-1">隨之需 <a class="header-anchor" href="#隨之需" aria-label="Permalink to “隨之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>釣曰厭部，善逐人走。來嫁無夫，不安其廬。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>曰，從宋元本，汲古、局本作目，均未詳其義，似用遇卦《隨》象。隨下震為人、為走、為逐，故曰善逐人走。震為嫁、為夫，二四震覆故無夫。艮為廬山，震動故不安。首句有訛字。</p><h3 id="隨之訟" tabindex="-1">隨之訟 <a class="header-anchor" href="#隨之訟" aria-label="Permalink to “隨之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>逐虎驅狼，避去不祥。凶惡北行，與喜相逢。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>通《明夷》。乾為虎，震為驅逐，坎為避，坤為不祥、為凶惡，坎位北，故北行，遇震而喜也。○虎，汲古作兔，喜作善，均依宋元本。</p><h3 id="隨之師" tabindex="-1">隨之師 <a class="header-anchor" href="#隨之師" aria-label="Permalink to “隨之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>齎貝贖狸，不聰我辭。繫於虎鬚，牽不得來。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《睽》。</p><h3 id="隨之比" tabindex="-1">隨之比 <a class="header-anchor" href="#隨之比" aria-label="Permalink to “隨之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>同載共輿，中道別去。喪我元夫，獨與孤居。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《革》。○同，元本訛岡，依宋本、汲古。居，汲古作苦，依宋元本。</p><h3 id="隨之小畜" tabindex="-1">隨之小畜 <a class="header-anchor" href="#隨之小畜" aria-label="Permalink to “隨之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>奮翅鼓翼，將之嘉國。愆期失時，反得所欲。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。震為翅、為翼、為鼓、為之、為嘉，坤為國，艮為時，坎陷，故愆期失時。震為樂，故曰反得所欲。○反，汲古作乃，從宋元本。</p><h3 id="隨之履" tabindex="-1">隨之履 <a class="header-anchor" href="#隨之履" aria-label="Permalink to “隨之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>目傾心惑，夏姬在側。申公顛倒，巫臣亂國。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>離目，伏坎為心、為惑。兌為姬，離為夏，故曰夏姬。伏震為公，離明，故曰申公。巽為顛，正反巽故曰顛倒。兌為巫，伏艮為臣、為國，離為亂，故曰巫臣亂國。《左傳》：&quot;楚滅陳，取夏姬，楚王及子反等皆欲娶之，皆為申公巫臣諫止，後巫臣自娶夏姬，奔晉，楚滅其家，巫臣乃遣其子適吳，教吳伐楚，子重、子反一歲七奔命。&quot;</p><h3 id="隨之泰" tabindex="-1">隨之泰 <a class="header-anchor" href="#隨之泰" aria-label="Permalink to “隨之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>摶鳩彈鵲，逐兔山北。丸盡日暮，失獲無得。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>坤為文，故為鳩。震為鵲，伏艮為手，故為摶、為彈。震為兔、為逐，乾為山，坤為北，故曰山北。乾為日、為丸，坤為暮、為失，故無得。○坤為鳩、為北證。○逐，汲古作獵，依宋元本。</p><h3 id="隨之否" tabindex="-1">隨之否 <a class="header-anchor" href="#隨之否" aria-label="Permalink to “隨之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>鹿求其子，虎廬之里。唐伯李耳，貪不我許。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>艮為鹿、為求、為虎、為廬、為里，伏震為子、為伯、為李，伏兌為耳。丁雲：《方言》，江淮南楚之間謂虎為李耳，關東西謂之伯都。唐伯、李耳，皆虎名也。○李，宋本訛季，從元本、汲古。</p><h3 id="隨之同人" tabindex="-1">隨之同人 <a class="header-anchor" href="#隨之同人" aria-label="Permalink to “隨之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>敗魚鮑室，臭不可息。上山履塗，歸傷我足。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>巽為魚、為敗、為鮑、為臭，乾為山，伏震為履、為塗、為足，坎折故傷足。又初二半震足不全，亦為傷也。○乾為山，《同人》三爻&quot;升其高陵&quot;，《易》即以乾為陵。</p><h3 id="隨之大有" tabindex="-1">隨之大有 <a class="header-anchor" href="#隨之大有" aria-label="Permalink to “隨之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>華燈百枝，消暗衰微。精光訖盡，奄如灰糜。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>離為燈，乾為百，兌為華，伏坎故暗，兌毀折，故衰微、故光盡。○宋元本作消衰暗微，依汲古。末句如、糜，各本作有、作縻，茲依《艮》之《蹇》校。</p><h3 id="隨之謙" tabindex="-1">隨之謙 <a class="header-anchor" href="#隨之謙" aria-label="Permalink to “隨之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>顏叔子夏，游遨仁宇。溫良受福，不失其所。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>艮為顏、為叔，震為子，伏離，故曰顏叔子夏。元刊註：顏叔，顏無繇也。震為游、為仁、為福，艮為宇，言顏叔、子夏同游聖門也。</p><h3 id="隨之豫" tabindex="-1">隨之豫 <a class="header-anchor" href="#隨之豫" aria-label="Permalink to “隨之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>梁柱堅固，子孫蕃盛。福喜盈積，終無禍悔。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為梁柱，艮為堅固，震為子，艮為孫，坤眾坎眾，故曰子孫蕃盛。震為福喜，坤為積、為禍悔。艮為終，震樂故無。○盛，依宋元本，汲古作熾。</p><h3 id="隨之隨" tabindex="-1">隨之隨 <a class="header-anchor" href="#隨之隨" aria-label="Permalink to “隨之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>鳥鳴東西，迎其群侶。似有所屬，不得自專，空返獨還。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥，震為鳴、為東，兌西，初四正覆艮，故迎其群侶。震為返、為還，震虛故空反，巽寡故獨還。○似有所屬四字，宋元無，依汲古。</p><h3 id="隨之蠱" tabindex="-1">隨之蠱 <a class="header-anchor" href="#隨之蠱" aria-label="Permalink to “隨之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>邊鄙不聳，民狎於野。穡人成功，年歲大有。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>艮居西北，故曰邊鄙。震為穡、為人、為功、為年歲。○聳，依宋元本，汲古作寧，非。於，依汲古，宋本作其。穡，依宋元本，汲古作嗇。</p><h3 id="隨之臨" tabindex="-1">隨之臨 <a class="header-anchor" href="#隨之臨" aria-label="Permalink to “隨之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>鼃池鳴呴，呼求水潦。雲雨大會，流成河海。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>震為鳴、為鼃，兌為池，坤為水潦，艮為求。兌為雨，坤為雲、為江海，重坤故大會。○鼃，汲古聲訛為蝸，宋本又訛為虵池、為牛，以兩本形聲定之必為鼃字。鼃，古文蛙字也。鳴呴呼求，依宋元本，汲古作鳴呵、作呼我。按：《春秋繁露》求雨法&quot;取五蝦蟇置池中，具酒脯陳請&quot;。</p><h3 id="隨之觀" tabindex="-1">隨之觀 <a class="header-anchor" href="#隨之觀" aria-label="Permalink to “隨之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>志合意同，姬薑相從。嘉耦在門，夫子悅喜。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>坤為志、為意，重坤故曰同。伏震為周，故為姬。巽為齊，故為薑。坤為耦、為門，伏震為夫子、為悅喜。</p><h3 id="隨之噬嗑" tabindex="-1">隨之噬嗑 <a class="header-anchor" href="#隨之噬嗑" aria-label="Permalink to “隨之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>白馬駁騮，更生不休。富有商人，利得如邱。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為白馬、為玄黃，故曰駁騮。為生，正反震，故更生不休，故富有。震為商人，伏巽為和，艮為邱。○駁騮，依宋元本，汲古作騮駁。</p><h3 id="隨之賁" tabindex="-1">隨之賁 <a class="header-anchor" href="#隨之賁" aria-label="Permalink to “隨之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>太姒夏禹，經啟九道。各有攸處，民得安所。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>禹，姒姓。離為夏，互震為王，故曰夏禹。震為啟、為大塗，數九，故曰九道。艮為處，坎為民，艮為安。</p><h3 id="隨之剝" tabindex="-1">隨之剝 <a class="header-anchor" href="#隨之剝" aria-label="Permalink to “隨之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>甲戊己庚，隨時轉行。不失其心，唐季發憤，擒滅子嬰。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《隨》象。隨互艮，艮外堅為甲，隨上互大坎，坎納戊，下互大離，離納己，震納庚，甲東方春，庚西方秋，坎戊冬，離已夏，故曰甲戊己庚，隨時轉行。震為帝，故曰唐，艮少故曰唐季、曰子嬰。艮手故曰擒，兌折故曰擒滅。唐季，謂高祖。劉向高祖頌：漢帝本系出自唐帝。班固述贊：皇矣大漢，纂堯之緒。○四五句宋元本作樂且安寧，依汲古。</p><h3 id="隨之復" tabindex="-1">隨之復 <a class="header-anchor" href="#隨之復" aria-label="Permalink to “隨之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>穆違百裡，使孟厲武。將師襲戰，敗於淆右。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>《左傳僖公三十三年》：&quot;秦穆公不聽蹇叔之諫，使百裡孟明視襲鄭敗於淆&quot;，而《史記》謂百裡奚與蹇叔並諫，故曰穆違百裡。坤為百裡，震為諸侯，故曰穆。震為孟、為武、為將師、為戰伐，坤喪故曰敗。○孟，依宋元本，汲古作明。</p><h3 id="隨之無妄" tabindex="-1">隨之無妄 <a class="header-anchor" href="#隨之無妄" aria-label="Permalink to “隨之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>茅茹本居，與類相投。願慕群旅，不離其巢。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>伏坤為茅茹，與乾為類，故相投合、故願慕群旅。震為旅，艮為巢，伏坤為願慕。○茅，汲古作茆。投，宋元本作扶，疑投是。易林每以十一尤與四豪協。</p><h3 id="隨之大畜" tabindex="-1">隨之大畜 <a class="header-anchor" href="#隨之大畜" aria-label="Permalink to “隨之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>伯仲叔季，日暮寢寐。坐卧失明，喪其貝囊。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>震為伯，伏大坎為仲，艮為叔季，乾為日，伏坤為暮、為寢寐，艮為坐卧，乾為明，坤失、坤喪、坤囊，艮為貝。○艮為貝證。</p><h3 id="隨之頤" tabindex="-1">隨之頤 <a class="header-anchor" href="#隨之頤" aria-label="Permalink to “隨之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>亡羊補牢，張氏失牛。騂駟奔走，鵠盜我魚。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>兌為羊，兌伏故亡羊。艮為牢，震為張，坤為牛，坤喪故失牛。震為騂駟、為奔走、為鵠，坤為魚、為我。</p><h3 id="隨之大過" tabindex="-1">隨之大過 <a class="header-anchor" href="#隨之大過" aria-label="Permalink to “隨之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>雀自燕顙，畏昏無光。思我狡童，不見子充。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>通《頤》。艮為雀，大離為目，兌為燕，艮為顙，故曰雀目燕顙。坤為昏、為畏，艮為光，坤黑，故無光。坤為思、為我，艮為童，震為子。狡童，《鄭風》篇名，淫女見絕於人之詩，故曰思、曰不見。不見子充，亦《鄭詩》語。</p><h3 id="隨之坎" tabindex="-1">隨之坎 <a class="header-anchor" href="#隨之坎" aria-label="Permalink to “隨之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>入暗出明，動作有光。運轉休息，常樂允康。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>伏巽為入，坎為暗，震為出，艮為光明，震為動作、為運轉，艮止故休息。震為樂、為康強。</p><h3 id="隨之離" tabindex="-1">隨之離 <a class="header-anchor" href="#隨之離" aria-label="Permalink to “隨之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>不勝私情，以利自嬰。北室出狐，毀其良家。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>互巽為利，伏坎為室、為北、為狐，伏艮為家，兌毀折艮伏，故曰毀其良家。嬰，絆也。陸機詩：世網嬰吾身。</p><h3 id="隨之咸" tabindex="-1">隨之咸 <a class="header-anchor" href="#隨之咸" aria-label="Permalink to “隨之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>稱幸上靈，媚悅於神。受福重重，子孫蕃功。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>兌為媚悅，伏震為神、為福，伏坤為重，震為子，艮為孫。蕃，多也。</p><h3 id="隨之恒" tabindex="-1">隨之恒 <a class="header-anchor" href="#隨之恒" aria-label="Permalink to “隨之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>齊薑叔子，天文在手。實沈參墟，封為康侯。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>巽為齊、為薑，伏震為子，艮為叔、為天，坤為文，艮為手，齊薑，武王后。叔子，即太叔。《左傳昭元年》：&quot;邑薑妊太叔時，夢天謂己曰：餘命爾子曰虞，及生，有文在其手曰虞&quot;，故曰天文在手。實沈、參墟，晉分野，皆艮象。震為諸侯、為康樂，故封為康侯。○文，依宋元本，汲古作命。多用伏象。</p><h3 id="隨之遯" tabindex="-1">隨之遯 <a class="header-anchor" href="#隨之遯" aria-label="Permalink to “隨之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>遨游無患，出入安全。長受其歡，君子萬年。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>伏震為遨游，坤為患，震樂故無患。震出巽入，艮為安，故出入安全。巽為長，震為歡，艮為君子，乾為萬年。</p><h3 id="隨之大壯" tabindex="-1">隨之大壯 <a class="header-anchor" href="#隨之大壯" aria-label="Permalink to “隨之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>被服文德，升入大麓。四門雍肅，登受大福。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>乾為被服，伏坤為文，故曰文德。艮為山麓，震為升，震卦數四，乾為門，故曰四門。乾為福、為大，震為登。《堯典》：&quot;賓於四門，四門穆穆。內於大麓，烈風雷雨弗迷&quot;，謂舜也。○汲古下有&quot;慈烏鳲鳩&quot;四句，與《乾》之《蒙》同，顯為另一林詞，宋元本無。</p><h3 id="隨之晉" tabindex="-1">隨之晉 <a class="header-anchor" href="#隨之晉" aria-label="Permalink to “隨之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>負金懷玉，南歸嘉國。蜂繭不螫，利入我室。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>艮為負、為金，乾為玉，乾伏，故曰懷玉。離為南，艮為國，坎為刺、為蜂蠆、為螫、為室。坤為我。</p><h3 id="隨之明夷" tabindex="-1">隨之明夷 <a class="header-anchor" href="#隨之明夷" aria-label="Permalink to “隨之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>日在阜顛，向昧為昏。小人成群，君子傷倫。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>離日艮阜，艮倒首向下與日連，故日在阜顛。坎為昧、為昏，言日至是不明也。坤為小人，坤坎皆為眾，故曰成群。艮為君子，艮倒故傷倫。倫，常也，言反常。</p><h3 id="隨之家人" tabindex="-1">隨之家人 <a class="header-anchor" href="#隨之家人" aria-label="Permalink to “隨之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>水父火母，先來鳴呴。澤皋之士，從高而處。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>伏震為父，與坎水連故曰水父。巽為母，與離火連故曰火母。《左傳》火為水妃是也。隨震為鳴呴、為士，兌為澤，艮為澤，艮為皋，澤皋之士，蓋猶山澤之士也。巽為高。○汲古作水火父母，此妄人不知震巽父母象，故將父火二字顛倒也。宋元本作水父海母，此音訛也。然由宋元及汲古三本互證其為水父火母無疑。士，從宋本，汲古訛上。皋，汲古訛高，依宋元本。</p><h3 id="隨之睽" tabindex="-1">隨之睽 <a class="header-anchor" href="#隨之睽" aria-label="Permalink to “隨之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>東鄰少女，為王長婦。柔順利貞，宜夫壽子。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>是用《隨》象。下震為東鄰，上兌為少女。震為王，巽為長婦、為柔順、為利，艮為貞，故曰柔順利貞。震為夫、為子，艮為壽。</p><h3 id="隨之蹇" tabindex="-1">隨之蹇 <a class="header-anchor" href="#隨之蹇" aria-label="Permalink to “隨之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>戴瓶望天，不見星辰。顧小失大，福逃於外。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>艮形似戴瓶，艮為望，為瓶所障，故不見天。艮為天、為星辰、為顧，兌為小。○顧，依宋元本，汲古作願。</p><h3 id="隨之解" tabindex="-1">隨之解 <a class="header-anchor" href="#隨之解" aria-label="Permalink to “隨之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>王喬無病，狗頭不痛。亡跛失履，乏我徒從。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>震為王、為喬木，王子喬，古仙人。坎為病，震解，故無病。遇卦《隨》互艮為狗、為頭坎、為痛，震解故不痛。坎為蹇、為跛，震為亡。亡，往也。為履，坎為失，故往跛失履。震為從。○亡跛徒從，依汲古，宋元本作三屍，作逆從。</p><h3 id="隨之損" tabindex="-1">隨之損 <a class="header-anchor" href="#隨之損" aria-label="Permalink to “隨之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>使燕築室，身無庇宿。家不容車，後我衣服。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>兌為燕，艮為室、為築、為身，身在外故無庇宿。艮為家，坤為大輿，燕室狹小，故家不容車。坤為衣服、為我，震為後。○後，從汲古，宋元本作微。</p><h3 id="隨之益" tabindex="-1">隨之益 <a class="header-anchor" href="#隨之益" aria-label="Permalink to “隨之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>威權分離，烏夜徘徊。爭蔽月光，大人誅傷。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>震為威，巽為權，風散故分離。艮為鳥，坤為夜，震起艮止，故徘徊。伏兌為月，巽為伏，故光蔽。乾為大人，坤死乾伏，故誅傷。又對象恆象，《大過》亦誅傷象也。○烏，從宋本，汲古、元本作烏，非，此似有故實。</p><h3 id="隨之夬" tabindex="-1">隨之夬 <a class="header-anchor" href="#隨之夬" aria-label="Permalink to “隨之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>辯變黑白，巧言亂國。大人失福，君子迷惑。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>此用《隨》象。兌為言，震亦為言，故曰辯、曰巧言。巽為白，兌為昧，故為黑。艮為國，乾為大人、為福，兌毀折，故失福。艮為君子，巽疑故迷惑。</p><h3 id="隨之姤" tabindex="-1">隨之姤 <a class="header-anchor" href="#隨之姤" aria-label="Permalink to “隨之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>衣踞鎧甲，敝筐受貝。大人不顧，少婦不取。棄捐於道。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>此用《隨》象。震為衣，艮為堅、為鎧甲、為貝，震為筐，巽為敝，故曰敝筐受貝。乾為大人，《大過》巽為女妻，故巽為少婦。伏震為大塗、為道，巽為隕落、為棄捐。林義未詳，韻亦不葉。○踞，汲古作鋸，受貝作為具，均依宋元本。首句似言鎧甲非常衣，次句言敝筐非盛具之器，故人皆不顧而棄捐於道也。</p><h3 id="隨之萃" tabindex="-1">隨之萃 <a class="header-anchor" href="#隨之萃" aria-label="Permalink to “隨之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>燕雀銜茅，以生孚乳。兄弟六人，姣好孝悌。得心歡欣，和悅相樂。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《兌》。○茅、姣，依宋元本，汲古作泥、作交。</p><h3 id="隨之升" tabindex="-1">隨之升 <a class="header-anchor" href="#隨之升" aria-label="Permalink to “隨之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>登幾上輿，駕駟南游。合從散橫，燕齊以強。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《泰》。○齊，依《泰》之《乾》，各本皆作秦。</p><h3 id="隨之困" tabindex="-1">隨之困 <a class="header-anchor" href="#隨之困" aria-label="Permalink to “隨之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>黷黷許許，仇偶相得。冰入炭室，消亡不息。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>黷黷，暗昧也。兌為暗昧，坎為眾，故曰許許。許許，同力合作之貌。《詩伐木》許許是也。坎離為夫婦，故曰仇偶。仇，匹也。坎為冰、為室，離火故曰炭室。兌毀折故不息。○偶，從宋元本，汲古作禍，非。</p><h3 id="隨之井" tabindex="-1">隨之井 <a class="header-anchor" href="#隨之井" aria-label="Permalink to “隨之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>鴟鴞破斧。邦人危殆，賴其忠德，轉禍為福，傾亡復立。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>伏艮為鴟鴞，兌為斧，兌毀故曰破斧。伏艮為邦，震為人，坎險故危殆。坎為忠，伏震為福。鴟鴞破斧，皆《豳風》篇名，皆詠周公，言三監叛，國勢危殆，周公復轉危為安也。○傾亡，依宋元本，汲古作傾危。兌為斧可解《易》斧象。</p><h3 id="隨之革" tabindex="-1">隨之革 <a class="header-anchor" href="#隨之革" aria-label="Permalink to “隨之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>載金販狗，利棄我走。藏匿淵底，悔折為咎。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。艮為金、為狗，震為載、為販、為走，巽為利，坎為藏匿，坤為淵、為悔，兌為折。○底，依《震》之《復》校，各本皆作渠。坤為淵證。</p><h3 id="隨之鼎" tabindex="-1">隨之鼎 <a class="header-anchor" href="#隨之鼎" aria-label="Permalink to “隨之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>淵坑復平，宇室安寧。憂患解除，賴福長生。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。坤為淵，坎為坑、為平，艮為宇室、為安寧，坎為憂患，震樂故解。震為福、為長生。○淵，依汲古，宋元本皆作泉。宇室，依宋元本，汲古作宇穴。</p><h3 id="隨之震" tabindex="-1">隨之震 <a class="header-anchor" href="#隨之震" aria-label="Permalink to “隨之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>孋姬讒喜，與二嬖謀。譖我恭子，賊害忠孝。申生以縊，重耳奔逃。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《履》。震為馬、為周、為姬，初四正反震，故曰讒、曰譖。震為生，伏巽為繩，故曰縊。坎為耳。○喜、嬖，從宋元本《比》之《履》校，各本皆作喜、作孽。又各本五六句皆作&quot;駕出嘉門，商伯有害&quot;，亦依《比》之《履》校。</p><h3 id="隨之艮" tabindex="-1">隨之艮 <a class="header-anchor" href="#隨之艮" aria-label="Permalink to “隨之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>刲羊不當，血少無羹。女執空筐，不得採桑。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>互震為羊，艮為刲，互坎為血。震為筐、為桑，艮手為執、為採。全取《歸妹》上六爻詞。○刲，宋元本作刺，非。</p><h3 id="隨之漸" tabindex="-1">隨之漸 <a class="header-anchor" href="#隨之漸" aria-label="Permalink to “隨之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>牧羊稻園，聞虎喧歡。畏懼悚息，終無禍患。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《節》。</p><h3 id="隨之歸妹" tabindex="-1">隨之歸妹 <a class="header-anchor" href="#隨之歸妹" aria-label="Permalink to “隨之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>明德隱伏，麟鳳遠匿。周室傾側，不知所息。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>離為明，坎隱伏。離為文、為麟鳳，坎匿故麟風遠匿。震為周、為室，艮覆故曰周室傾仄。艮止為息，艮覆故不知所息。</p><h3 id="隨之豐" tabindex="-1">隨之豐 <a class="header-anchor" href="#隨之豐" aria-label="Permalink to “隨之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>鄰不我願，而求玉女。身多禿癩，誰肯媚者。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>離為東鄰、為願，互大坎，坎隱伏故不願。震為玉，兌為女，伏艮為求、為身，艮多節，故曰禿癩。兌為媚。林詞大意言不自知而妄求，必不得也。○玉女，汲古作寶玉，依宋元本。</p><h3 id="隨之旅" tabindex="-1">隨之旅 <a class="header-anchor" href="#隨之旅" aria-label="Permalink to “隨之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>初雖無輿，後得戰車。賴幸逢福，得離兵革。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>震為車，震伏故無。伏節，中爻正覆震，亦正覆艮，兩車兩手相對故曰戰車。震為福，正覆震故曰逢福。離為兵革，在外故離兵革。○戰車，依宋元本，汲古作載車。得離，從汲古，宋元本作不離。</p><h3 id="隨之巽" tabindex="-1">隨之巽 <a class="header-anchor" href="#隨之巽" aria-label="Permalink to “隨之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>水壞我里，東流為海。龜鳧歡囂，不睹王母。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《兌》。兌巽象同。</p><h3 id="隨之兌" tabindex="-1">隨之兌 <a class="header-anchor" href="#隨之兌" aria-label="Permalink to “隨之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>兩心不同，或欲西東。明論終始，莫適所從。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。坎為心，兌卦數二，故曰兩心。兌西，互震為東，故或欲西東。震為始，艮為終，震為言論。適，主也。震為主、為從，艮三至上正反震，故莫適所從也。</p><h3 id="隨之渙" tabindex="-1">隨之渙 <a class="header-anchor" href="#隨之渙" aria-label="Permalink to “隨之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>天帝懸車，廢禮不朝。攘服不制，失其寵家。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>中爻艮為天，震為帝、為車，三至五震覆，故曰懸車。元刊註天文有帝車星，故曰天帝懸車。震為晉、為朝，三至五震覆，故曰不朝。艮手為攘，震為服，艮手為制，正反艮故不制。艮為家，坎失。又攘服者，蓋遠於要服荒服，必待攘而後服也。攘服，依汲古，宋元本作欀福，非。又或謂制當作至，亦非。末句汲古作失寵其家，依宋元本。</p><h3 id="隨之節" tabindex="-1">隨之節 <a class="header-anchor" href="#隨之節" aria-label="Permalink to “隨之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>交川合浦，遠濕難處。水土不同，思吾皇祖。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>坤為水，陽入坤成坎，故曰交川合浦。交川，即交州，皆南越地名。坎為交、為合也，坎為濕，坎險故難處。震為皇，艮為祖，坎為思。○艮為祖證。</p><h3 id="隨之中孚" tabindex="-1">隨之中孚 <a class="header-anchor" href="#隨之中孚" aria-label="Permalink to “隨之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>勾踐之危，棲於會稽。太宰機言，越國復存。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為足、為踐、為王，故曰勾踐。兌毀折故危，艮止故曰棲，艮山故曰會稽。震為主、為宰、為言，坎為機，艮為國，震為南，故曰越國。《史記》：&quot;越王兵敗，棲會稽山，賂太宰嚭，說吳王，王竟許越平&quot;。○機，汲古作譏，依宋元本。</p><h3 id="隨之小過" tabindex="-1">隨之小過 <a class="header-anchor" href="#隨之小過" aria-label="Permalink to “隨之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>慈烏鳲鳩，執一無尤。寢門內治，君子悅喜。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>《詩曹風》：&quot;鳲鳩在桑，其子七兮；淑人君子，其儀一兮&quot;。艮為烏，兌悅故曰慈烏。艮為鳲鳩。《爾雅》註：布穀也。艮為執，互大坎數一，故曰執一。艮為寢、為門、為君子。震為喜。○鳲，宋元本訛鳴，依汲古。</p><h3 id="隨之既濟" tabindex="-1">隨之既濟 <a class="header-anchor" href="#隨之既濟" aria-label="Permalink to “隨之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>富年早寡，獨立孤居，雞鳴犬吠。無敢問諸，我生不遇，獨罹寒苦。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此多取《隨》象。震為年、為早，巽為寡，艮為孤，震為獨，艮為居，《既濟》坎亦為孤，《睽九四》&quot;睽孤&quot;是也。巽為雞，震為鳴吠，艮為犬，震為問、為生。坎為寒。○富年，依汲古，宋元本作當年。獨立孤居，汲古作獨與孤居，諸作者，均依宋元本。</p><h3 id="隨之未濟" tabindex="-1">隨之未濟 <a class="header-anchor" href="#隨之未濟" aria-label="Permalink to “隨之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>江海變服，淫湎無側。高位顛崩，寵祿反覆。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>《書洪範》：&quot;無反無側&quot;，註：不偏邪也。重坎故曰江海、曰淫湎。高位顛崩，似仍指《隨》象，《隨》艮覆在下故曰崩。○無側，從宋元本，汲古作測，義均未協。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
